1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	/**
6	 * Formats and reads an owner's customer code as {@code <REGION>-<HASH8>}, where
7	 * {@code REGION} is the region code derived from the owner's postcode (see
8	 * {@link org.springframework.samples.petclinic.model.CityRegion}) and {@code HASH8} is the
9	 * first 8 upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}
10	 * (e.g. {@code NSW-1A2B3C4D}). The code is derived purely from the owner's own fields, so
11	 * the same owner always yields the same code without any sequence or coordination.
12	 */
13	public final class CustomerCode {
14	
15	    /** Number of hex characters kept from the telephone-and-name hash. */
16	    private static final int HASH_LENGTH = 8;
17	
18	    private CustomerCode() {
19	    }
20	
21	    /**
22	     * The customer code for an owner in {@code region} whose normalized telephone and last
23	     * name are given.
24	     */
25	    public static String format(String region, String normalizedTelephone, String lastName) {
26	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
27	        String last = lastName == null ? "" : lastName;
28	        return region + "-" + Hashes.upperHexPrefix(telephone + last, HASH_LENGTH);
29	    }
30	
31	    /**
32	     * De-duplicates {@code code} against the codes already {@code taken}. Returns {@code code}
33	     * unchanged when it is free; otherwise appends {@code -<n>} with the smallest {@code n} of 2
34	     * or more that yields a code not in {@code taken} (e.g. {@code NSW-1A2B3C4D-2}).
35	     */
36	    public static String deduplicate(String code, Set<String> taken) {
37	        if (!taken.contains(code)) {
38	            return code;
39	        }
40	        for (int n = 2; ; n++) {
41	            String candidate = code + "-" + n;
42	            if (!taken.contains(candidate)) {
43	                return candidate;
44	            }
45	        }
46	    }
47	
48	    /**
49	     * The {@code REGION} segment of a customer code — everything before the first {@code -}
50	     * separator, i.e. the region the code was minted in.
51	     */
52	    public static String region(String customerCode) {
53	        int separator = customerCode.indexOf('-');
54	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
55	    }
56	}
