1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * The identity key summarising who an owner is for duplicate detection: the full lower-case
8	 * SHA-256 hex of {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, each
9	 * part canonicalized the same way it is stored (E.164 telephone, lower-cased email, Soundex of
10	 * the last name). Two owners collide only when all three parts match, so a differing telephone
11	 * yields a different key. Duplicate rejection (409) is keyed on this value (see
12	 * {@link EnsureUniqueIdentity}) and it is also exposed on the response.
13	 */
14	public final class IdentityKeys {
15	
16	    private IdentityKeys() {
17	    }
18	
19	    /** The identity key of an existing owner, derived from its stored fields. */
20	    public static String of(Owner owner) {
21	        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
22	    }
23	
24	    /** The identity key a create request resolves to, from its (normalized) fields. */
25	    public static String of(OwnerFieldsDto request) {
26	        return key(request.getTelephone(), request.getEmail(), request.getLastName());
27	    }
28	
29	    private static String key(String telephone, String email, String lastName) {
30	        String normalizedTelephone = telephone == null ? ""
31	                : Telephones.toE164(telephone).orElse(telephone);
32	        String lowerEmail = email == null || email.isBlank() ? "" : Emails.normalize(email);
33	        String soundex = Soundex.encode(lastName);
34	        return Hashes.lowerHex(normalizedTelephone + "|" + lowerEmail + "|" + soundex);
35	    }
36	}
