1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.CityRegion;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns a new owner's customer code before it is saved. The code is {@code <REGION>-<HASH8>}
13	 * (see {@link CustomerCode}): the region derived from the owner's postcode plus a hash of the
14	 * owner's normalized telephone and last name. Runs after the telephone has been normalized, so
15	 * {@link Owner#getTelephone()} already holds the canonical form the hash is taken over. Should
16	 * that code collide with an existing owner's, it is de-duplicated with a {@code -<n>} suffix.
17	 */
18	public class AssignCustomerCode {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String region = CityRegion.localityOf(owner.getPostcode(), owner.getCity());
22	        String code = CustomerCode.format(region, owner.getTelephone(), owner.getLastName());
23	        Set<String> taken = new HashSet<>();
24	        for (Owner existing : ownerRepository.findAllActive()) {
25	            if (existing.getCustomerCode() != null) {
26	                taken.add(existing.getCustomerCode());
27	            }
28	        }
29	        owner.setCustomerCode(CustomerCode.deduplicate(code, taken));
30	    }
31	}
