11	/**
12	 * Emits audit output for a successfully created owner. Runs after {@link SaveOwner} so the
13	 * generated id is available, writing both a human-readable audit line and an immutable
14	 * structured {@link OwnerCreatedEvent} (as JSON) to the dedicated {@code AUDIT} logger. The
15	 * structured event carries a monotonic {@code seq} from {@link AuditSequence}.
16	 */
17	public class AuditOwnerCreated {
18	
19	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
20	
21	    public void service(@Val Owner owner, AuditSequence sequence) {
22	        AUDIT.info(
23	                "Owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
24	                        + "membershipNumber={}",
25	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
26	                MembershipLevel.of(owner), MembershipNumber.of(owner));
27	        AUDIT.info(OwnerCreatedEvent.of(sequence.next(), owner).toJson());
28	    }
29	}
