3	import tools.jackson.databind.ObjectMapper;
4	
5	import org.springframework.samples.petclinic.model.MembershipLevel;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * An immutable structured audit event for a created owner. Serialized to the JSON object
10	 * {@code {seq, ownerId, customerCode, membershipLevel, event}} (field order preserved),
11	 * where {@code event} is always {@link #EVENT_NAME} and {@code customerCode} carries the
12	 * owner's {@link Owner#getPrimaryIdentifier() current primary identifier} — so when that
13	 * identifier becomes the member id, this event carries the member id without further change.
14	 */
15	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
16	        int membershipLevel, String event) {
17	
18	    /** The fixed event marker for a created owner. */
19	    public static final String EVENT_NAME = "OWNER_CREATED";
20	
21	    private static final ObjectMapper JSON = new ObjectMapper();
22	
23	    /**
24	     * The event for {@code owner}, stamped with {@code seq}, reading the owner's primary
25	     * identifier and current membership level.
26	     */
27	    public static OwnerCreatedEvent of(long seq, Owner owner) {
28	        return new OwnerCreatedEvent(seq, owner.getId(), owner.getPrimaryIdentifier(),
29	                MembershipLevel.of(owner), EVENT_NAME);
30	    }
31	
32	    /** This event as its JSON representation. */
33	    public String toJson() {
34	        return JSON.writeValueAsString(this);
35	    }
36	}
