3	/**
4	 * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where {@code YY}
5	 * is the last two digits of the {@link FiscalYear fiscal year} of the (business-day-adjusted)
6	 * registration date, e.g. {@code SMI-0007-M26}.
7	 */
8	public final class MembershipNumber {
9	
10	    private MembershipNumber() {
11	    }
12	
13	    /** The membership number for the given owner (see {@link MembershipNumber}). */
14	    public static String of(Owner owner) {
15	        String yy = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
16	        return owner.getCustomerCode() + "-M" + yy;
17	    }
18	}
