1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * The Luhn check-digit algorithm. Non-digit characters are ignored, so the digit is
5	 * computed over the digits contained in the given string.
6	 */
7	public final class Luhn {
8	
9	    private Luhn() {
10	    }
11	
12	    /**
13	     * The Luhn check digit (0-9) over the digits contained in {@code value}, computed by
14	     * doubling every second digit from the right (subtracting 9 when the result exceeds 9),
15	     * summing, and taking the amount needed to reach the next multiple of ten.
16	     */
17	    public static int checkDigit(String value) {
18	        int sum = 0;
19	        boolean dbl = true;
20	        for (int i = value.length() - 1; i >= 0; i--) {
21	            char c = value.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int d = c - '0';
26	            if (dbl) {
27	                d *= 2;
28	                if (d > 9) {
29	                    d -= 9;
30	                }
31	            }
32	            sum += d;
33	            dbl = !dbl;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
