1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * The fiscal year a date falls in. The fiscal year starts on 1 July and is named by the
8	 * calendar year in which it ends, so 1 July 2025 - 30 June 2026 is fiscal year 2026. This is
9	 * the single source of the fiscal-year basis shared by the membership number's year segment
10	 * ({@link MembershipNumber}), the tenure count ({@link MembershipLevel}) and the owner's
11	 * {@code fiscalYear} field.
12	 */
13	public final class FiscalYear {
14	
15	    /** The month a fiscal year starts on. */
16	    private static final Month START_MONTH = Month.JULY;
17	
18	    private FiscalYear() {
19	    }
20	
21	    /**
22	     * The fiscal year that {@code date} falls in: its calendar year, or the next calendar
23	     * year once the date is on or after 1 July.
24	     */
25	    public static int of(LocalDate date) {
26	        int year = date.getYear();
27	        return date.getMonthValue() >= START_MONTH.getValue() ? year + 1 : year;
28	    }
29	
30	    /** The fiscal year of {@code date} formatted as {@code FY<YY>}, e.g. {@code FY26}. */
31	    public static String label(LocalDate date) {
32	        return String.format("FY%02d", of(date) % 100);
33	    }
34	
35	    /**
36	     * The number of fiscal years elapsed between {@code from} and {@code to}: the difference
37	     * of their fiscal years, so a span that crosses one 1 July boundary is one elapsed
38	     * fiscal year.
39	     */
40	    public static int elapsed(LocalDate from, LocalDate to) {
41	        return of(to) - of(from);
42	    }
43	}
