1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * The owner's marketing segment, formatted as {@code <TIER>_<AREA>}, one of
5	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
6	 * {@code STANDARD_REGIONAL}. It composes two independent axes derived at read time:
7	 *
8	 * <ul>
9	 *   <li>{@link Tier} — {@link Tier#PREMIUM} at {@link #PREMIUM_MIN_LEVEL membership level 3}
10	 *   or more, otherwise {@link Tier#STANDARD}.</li>
11	 *   <li>{@link Area} — {@link Area#METRO} when the locality is a
12	 *   {@link CityRegion#isKnownRegion(String) known region} (NSW, VIC or QLD), otherwise
13	 *   {@link Area#REGIONAL}.</li>
14	 * </ul>
15	 */
16	public final class OwnerSegment {
17	
18	    /** The membership level at or above which the owner is {@link Tier#PREMIUM}. */
19	    public static final int PREMIUM_MIN_LEVEL = 3;
20	
21	    /** The membership pricing tier axis of the segment. */
22	    public enum Tier {
23	        PREMIUM, STANDARD;
24	
25	        /** The tier for the given membership level: {@link #PREMIUM} at
26	         *  {@link #PREMIUM_MIN_LEVEL} or more, otherwise {@link #STANDARD}. */
27	        public static Tier of(int membershipLevel) {
28	            return membershipLevel >= PREMIUM_MIN_LEVEL ? PREMIUM : STANDARD;
29	        }
30	    }
31	
32	    /** The geographic area axis of the segment. */
33	    public enum Area {
34	        METRO, REGIONAL;
35	
36	        /** The area for the given locality: {@link #METRO} for a
37	         *  {@link CityRegion#isKnownRegion(String) known region}, otherwise
38	         *  {@link #REGIONAL}. */
39	        public static Area of(String locality) {
40	            return CityRegion.isKnownRegion(locality) ? METRO : REGIONAL;
41	        }
42	    }
43	
44	    private OwnerSegment() {
45	    }
46	
47	    /**
48	     * The segment for the given membership level and locality, formatted as
49	     * {@code <TIER>_<AREA>}.
50	     */
51	    public static String of(int membershipLevel, String locality) {
52	        return Tier.of(membershipLevel) + "_" + Area.of(locality);
53	    }
54	}
