1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * The owner's membership scoring. Points start at 0 and accrue independently:
7	 * {@link #EMAIL_POINTS} when an email address is present, {@link #NO_NAMESAKE_POINTS} when
8	 * the owner has no namesakes ({@code namesakeCount} is 0), {@link #HOUSEHOLD_POINTS} for a
9	 * household of {@link #HOUSEHOLD_MIN} or more, and {@link #TENURE_POINTS} once the owner's
10	 * tenure reaches at least {@link #TENURE_FISCAL_YEARS} elapsed {@link FiscalYear fiscal
11	 * year}. Those points map to a level from 1 to 4 (see {@link #level(int)}). A newly created
12	 * owner has zero elapsed fiscal years, so tenure points never apply at creation.
13	 */
14	public final class MembershipLevel {
15	
16	    /** Points awarded when an email address is present. */
17	    public static final int EMAIL_POINTS = 2;
18	
19	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
20	    public static final int NO_NAMESAKE_POINTS = 1;
21	
22	    /** Points awarded for a household of {@link #HOUSEHOLD_MIN} or more. */
23	    public static final int HOUSEHOLD_POINTS = 2;
24	
25	    /** The household size at or above which {@link #HOUSEHOLD_POINTS} is awarded. */
26	    public static final int HOUSEHOLD_MIN = 3;
27	
28	    /** Points awarded once the owner's tenure reaches {@link #TENURE_FISCAL_YEARS} elapsed
29	     *  fiscal years. */
30	    public static final int TENURE_POINTS = 3;
31	
32	    /** The number of elapsed fiscal years the tenure must reach to earn {@link #TENURE_POINTS}. */
33	    public static final int TENURE_FISCAL_YEARS = 1;
34	
35	    private MembershipLevel() {
36	    }
37	
38	    /**
39	     * The membership points for the given owner as of today (see
40	     * {@link #points(Owner, LocalDate)}).
41	     */
42	    public static int points(Owner owner) {
43	        return points(owner, LocalDate.now());
44	    }
45	
46	    /**
47	     * The membership points for the given owner as of {@code asOf}: 0 plus
48	     * {@link #EMAIL_POINTS} when an email address is present, {@link #NO_NAMESAKE_POINTS}
49	     * when the owner has no namesakes, {@link #HOUSEHOLD_POINTS} for a household of
50	     * {@link #HOUSEHOLD_MIN} or more, and {@link #TENURE_POINTS} once the owner's tenure
51	     * reaches at least {@link #TENURE_FISCAL_YEARS} elapsed fiscal years.
52	     */
53	    public static int points(Owner owner, LocalDate asOf) {
54	        int points = 0;
55	        if (owner.hasEmail()) {
56	            points += EMAIL_POINTS;
57	        }
58	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
59	            points += NO_NAMESAKE_POINTS;
60	        }
61	        Integer householdMemberCount = owner.getHouseholdMemberCount();
62	        if (householdMemberCount != null && householdMemberCount >= HOUSEHOLD_MIN) {
63	            points += HOUSEHOLD_POINTS;
64	        }
65	        if (hasTenure(owner, asOf)) {
66	            points += TENURE_POINTS;
67	        }
68	        return points;
69	    }
70	
71	    /**
72	     * The membership level for the given {@code points}: 1 for 0-1 points, 2 for 2-3, 3 for
73	     * 4-5, and 4 for 6 or more.
74	     */
75	    public static int level(int points) {
76	        if (points <= 1) {
77	            return 1;
78	        }
79	        if (points <= 3) {
80	            return 2;
81	        }
82	        if (points <= 5) {
83	            return 3;
84	        }
85	        return 4;
86	    }
87	
88	    /**
89	     * The membership level for the given owner as of today (see
90	     * {@link #of(Owner, LocalDate)}).
91	     */
92	    public static int of(Owner owner) {
93	        return of(owner, LocalDate.now());
94	    }
95	
96	    /**
97	     * The membership level for the given owner as of {@code asOf}: {@link #points(Owner,
98	     * LocalDate)} mapped to a level by {@link #level(int)}, then held at or below the
99	     * owner's {@link Owner#getMembershipLevelCap() household ceiling} when one applies.
100	     */
101	    public static int of(Owner owner, LocalDate asOf) {
102	        int level = level(points(owner, asOf));
103	        Integer cap = owner.getMembershipLevelCap();
104	        return cap == null ? level : Math.min(level, cap);
105	    }
106	
107	    /**
108	     * Whether the owner's tenure at {@code asOf} reaches at least
109	     * {@link #TENURE_FISCAL_YEARS} elapsed fiscal years since registration.
110	     */
111	    private static boolean hasTenure(Owner owner, LocalDate asOf) {
112	        LocalDate registrationDate = owner.getRegistrationDate();
113	        return registrationDate != null
114	            && FiscalYear.elapsed(registrationDate, asOf) >= TENURE_FISCAL_YEARS;
115	    }
116	}
