3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Shared SHA-256 hashing used to derive stable identifiers from an owner's own fields
10	 * (the customer code, the household id and the identity key). Callers take either the full
11	 * lower-case hex digest or a fixed-length upper-case prefix, so the derivation lives here once
12	 * rather than being copied per caller.
13	 */
14	final class Hashes {
15	
16	    private Hashes() {
17	    }
18	
19	    /**
20	     * The full SHA-256 digest of {@code value} rendered as lower-case hex over the UTF-8 bytes
21	     * of the input (64 hex characters).
22	     */
23	    static String lowerHex(String value) {
24	        return hex(value);
25	    }
26	
27	    /**
28	     * The first {@code length} characters of the SHA-256 digest of {@code value}, rendered
29	     * as upper-case hex over the UTF-8 bytes of the input.
30	     */
31	    static String upperHexPrefix(String value, int length) {
32	        return hex(value).substring(0, length).toUpperCase(Locale.ROOT);
33	    }
34	
35	    private static String hex(String value) {
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                    .digest(value.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder hex = new StringBuilder(digest.length * 2);
40	            for (byte b : digest) {
41	                hex.append(String.format("%02x", b));
42	            }
43	            return hex.toString();
44	        }
45	        catch (NoSuchAlgorithmException e) {
46	            throw new IllegalStateException("SHA-256 not available", e);
47	        }
48	    }
49	}
