8	/**
9	 * The duplicate block: rejects a create request whose {@link IdentityKeys identity key} — its
10	 * normalized telephone, lower-cased email and last-name Soundex — matches an existing owner's,
11	 * because that is a re-registration of the same identity. Owners flagged deleted are ignored.
12	 * The email-domain blocklist runs earlier in the pipeline, so a blocked domain is rejected
13	 * before this check. Owners in one household with different telephones no longer collide here;
14	 * they are surfaced as a soft match instead (see {@link DetectPossibleDuplicate}).
15	 */
16	public class EnsureUniqueIdentity {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String identityKey = IdentityKeys.of(request);
21	        for (Owner existing : ownerRepository.findAllActive()) {
22	            if (identityKey.equals(IdentityKeys.of(existing))) {
23	                throw new DuplicateIdentityException(identityKey);
24	            }
25	        }
26	    }
27	}
